insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('mangga', 'Mangga', 'Mangifera indica', 'buah', 'sedang', 1200, 'sedang', 'terang penuh', 'Panen utama musim kering (Agustus–November)', 'Mangga adalah raja buah tropis Indonesia dengan pasar yang tak pernah surut — varietas harum manis, gedong gincu, dan madu selalu dicari saat musim panen. Pohon mangga tahan panas dan cocok sekali untuk iklim Kaltim; bibit cangkok/greft mulai berbuah di tahun ke-3–4, jauh lebih cepat dari tanam benih. Dengan teknik pembungaan paksa (perangsang bunga), panen bisa diatur jatuh di musim kemarau ketika harga tertinggi. Mangga juga fleksibel dijual: segar, diproses manisan, jus, hingga dijual per pohon ke penadah buah.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5cb174793447.png', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5cb174793447.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0e9f41e2e83f.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/528cdc742b14.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/d71ab90cea27.webp"]', '["Tanam bibit cangkok/greft unggul (harum manis, gedong, madu) di lubang 60×60 cm bercampur kandang matang, jarak 8–10 meter.", "Siram tunta di tahun pertama dan pasang peneduh sementara; beri mulsa jerami menjaga lembap.", "Bentuk tajuk sejak muda — potong tunas tegak agar ranting menyamping dan mudah dipanen.", "Panen buah matang pohon saat kulit mulai menguning dan getah mengental (120 hari dari bunga); gunakan gunting panjang dengan pangkasan buah."]', '["Pupuk kandang 20–30 kg/pohon tiap akhir musim hujan ditambah NPK untuk mendukung pembungaan.", "Perangsang bunga saat kemarau (penghentian air + semprotan perangsang) mengatur panen di harga terbaik.", "Rutin pangkas ranting kering dan tumpang tindih agar matahari masuk dan risiko serangan hama turun.", "Bungkus buah muda dengan kertas/kantong plastik khusus untuk buah bebas cacat bernilai premium."]', '[{"name": "Antraknosa", "symptom": "Bercak hitam cekung pada buah dan bunga menghitam gugur, terutama saat hujan.", "treatment": "Bungkus buah muda, semprot fungisida tembaga saat bunga, pangkas tajuk agar kering cepat."}, {"name": "Kepik Penghisap Buah", "symptom": "Bintik cekung kehitaman pada kulit buah dengan daging berambut di dalam.", "treatment": "Bungkus buah sejak ukuran kelereng, pungut keper pagi, bersihkan gulma di bawah pohon."}, {"name": "Lalat Buah", "symptom": "Buah berluka lembut dan membusuk dari dalam; larva putih ditemukan di daging buah.", "treatment": "Pasang perangkap lalat (methyl eugenol), segera angkat buah jatuh, dan bungkus buah muda."}]', 'Rp 8.000 – 25.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('manggis', 'Manggis', 'Garcinia mangostana', 'buah', 'sulit', 2920, 'banyak', 'teduh sebagian', 'Panen musim hujan akhir (Desember–Maret)', 'Manggis adalah buah khas Kalimantan Timur yang paling terkenal — manggis Kedondong di Kutai Kartanegara bahkan menjadi produk unggulan daerah dengan cita rasa manis legit yang tak tertandingi. Buah berjuluk ratu buah ini dipasarkan sampai luar provinsi dengan harga premium, dan permintaannya jauh melampaui pasokan lokal. Pohonnya lambat (panen pertama 8–10 tahun dari benih) namun sangat produktif selama puluhan tahun, menjadikannya investasi jangka panjang yang berharga untuk tanah keluarga. Dengan tanda buah Kaltim yang sudah dikenal pasar, menanam manggis hari ini adalah aset panen besar di masa depan.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/58fd0dba62f1.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/58fd0dba62f1.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5cdd71990a1b.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/eaf009e4ca03.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cfe6e89a3389.jpg"]', '["Tanam benih/bibit manggis di lubang 60×60 cm dengan campuran kandang; manggis paling baik ditanam dari benih langsung.", "Jarak tanam 10×10 meter; pasang tanaman peneduh sementara (pisang) selama 2–3 tahun pertama.", "Siram rutin — manggis pecah air; mulsa jerami tebal di sekitar pohon sangat membantu.", "Panen buah saat kulit ungu penuh dan tangkai hijau segar; gunting dengan tangkai agar tahan simpan lebih lama."]', '["Jaga kelembapan sepanjang tahun — kekeringan panjang membuat pohon stres dan buah gagal isi.", "Pupuk kandang tiap 6 bulan; pohon dewasa sangat menghargai kompos tebal di bawah tajuk.", "Peneduh muda wajib: semangil manggis muda gugur daun bila terik langsung sejak semai.", "Bersihkan rumput liar dan biarkan tanaman penutup tanah rendah agar kelembapan tanah stabil."]', '[{"name": "Gugur Bunga dan Buah Muda", "symptom": "Bunga dan buah kecil gugur massal saat hujan deras bersambung atau serangan jamur.", "treatment": "Semprot fungisida tembaga saat musim bunga, pastikan drainase baik di bawah pohon."}, {"name": "Lalat Buah", "symptom": "Kulit buah berluka basah dan daging menjadi berair busuk dari dalam.", "treatment": "Pasang perangkap feromon di kebun, angkat buah jatuh, panen buah saat baru penuh ungu."}, {"name": "Busuk Akar", "symptom": "Daun menguning, pohon layu perlahan; akar utama membusuk saat tanah terlalu tergenang.", "treatment": "Perbaiki drainase, aplikasi Trichoderma, hindari menanam di lahan genangan permanen."}]', 'Rp 15.000 – 40.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('rambutan', 'Rambutan', 'Nephelium lappaceum', 'buah', 'sedang', 1460, 'banyak', 'terang penuh', 'Panen musim hujan akhir (November–Februari)', 'Rambutan adalah buah musiman paling ditunggu di Kalimantan — saat panen tiba, pasar dan jalan desa penuh pedagang rambutan merah dan kuning. Varietas unggul seperti binjai, lebak bulus, dan rapiah berbuah gemuk, manis, dan tak menempel di biji, harganya bisa dua kali lipat rambutan biasa. Pohon rambutan tumbuh subur di Kaltim dan mulai berbuah di tahun ke-4–5 dari bibit cangkok, produktif selama puluhan tahun. Selain buah segar, rambutan laku dijual tetap di tandan ke pengepul, praktis untuk petani dengan jumlah panen besar.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b983a7c63cd2.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b983a7c63cd2.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3c24865ebe55.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cb6a0719b7f8.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ae5a28604f14.jpg"]', '["Tanam bibit cangkok varietas unggul (binjai, rapiah) jarak 8–10 meter di lubang bercampur kandang.", "Siram tunta tahun pertama; beri mulsa dan tanaman peneduh sementara bila lahan terbuka lebar.", "Bentuk tajuk muda dengan pemangkasan ringan agar ranting seimbang dan panen mudah.", "Panen seluruh tandan saat warna bulu penuh merah/kuning dan rasa sudah manis — gunakan gunting tandan."]', '["Pupuk kandang tiap 6 bulan ditambah NPK sebelum musim bunga untuk memperpadat pembungaan.", "Rambutan butuh musim kering singkat untuk memicu bunga — pastikan drainase baik musim hujan.", "Pangkas cabut-cabut kering dan ranting dalam untuk sirkulasi udara dan cahaya merata.", "Panen penuh tandan dengan gunting; jangan petik buah satuan di pengepul besar karena cepat rusak."]', '[{"name": "Lalat Buah", "symptom": "Buah berluka lembut, kulit kusam, dan daging berair busuk dengan larva di dalam.", "treatment": "Perangkap feromon per pohon, buah jatuh diangkat dan dikubur, panen tepat matang."}, {"name": "Kepik Penghisap", "symptom": "Buah bercak cekung gelap dan gugur muda sebelum matang.", "treatment": "Pungut keper manual pagi hari, sempestkan kebersihan kebun, bungkus tandan unggul."}, {"name": "Busuk Buah Musim Hujan", "symptom": "Buah matang berbulu cokelat berair cepat saat hujan terus-menerus di puncak panen.", "treatment": "Panen segera saat matang penuh, jangan ditunda; angkat buah busuk dari tanah dan kebun."}]', 'Rp 8.000 – 20.000 / kg')
