insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('nangka', 'Nangka', 'Artocarpus heterophyllus', 'buah', 'mudah', 1460, 'sedang', 'terang penuh', 'Sepanjang tahun, puncak musim hujan', 'Nangka adalah pohon serbaguna bernilai ekonomi tinggi: buah matang manis laku di pasar, nangka muda jadi bahan sayur dan olahan, bahkan kayunya dicari industri mebel. Pohonnya sangat mudah — tumbuh di hampir semua tanah Kaltim, tahan kemarau, dan mulai berbuah tahun ke-4 dari benih unggul. Satu pohon dewasa bisa menghasilkan puluhan buah per musim dengan berat 10–30 kg per buah, sehingga satu-dua pohon saja sudah bernilai jutaan rupiah per panen. Varietas nangka karimaga empuk manis yang populer bisa dipilih untuk pasar buah segar.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/d052026a4ed8.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/d052026a4ed8.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/afe962d8ad47.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/dd2aec31bb30.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/96d96b100092.jpg"]', '["Tanam benih segar langsung atau bibit unggul di lubang 50×50 cm, jarak 10×10 meter dari bangunan dan pohon lain.", "Siram tunta tahun pertama; beri mulsa daun dan lindungi dari ternak muda yang suka makan anakan.", "Pangkas tunas paling bawah saat pohon 2 meter agar tajuk terbentuk dan panen tak terlalu tinggi.", "Panen buah saat kulit berbau harum, duri melebar, dan berbunyi berongga saat diketuk — turunkan dengan tali dua orang."]', '["Pupuk kandang tiap awal musim hujan; pohon dewasa jarang butuh perawatan intensif.", "Buang buah kecil berlebihan — pohon terlalu banyak buah akan menghasilkan buah kecil semua.", "Jaga kebersihan sekitar pohon dan pangkas cabut kering untuk mencegah hama batang.", "Panen di pagi hari dan jangan jatuhkan buah — benturan membuat daging lembek cepat busuk."]', '[{"name": "Penggerek Batang", "symptom": "Ada lubang serbuk gergaji di batang; cabut mengering dan pohon melemah perlahan.", "treatment": "Tutup lubang dengan campuran pestisida+parafin, pangkas cabut terinfeksi, jaga pohon sehat."}, {"name": "Buah Busuk", "symptom": "Bercak hitam berair pada buah muda yang membusuk dan gugur saat hujan lembap.", "treatment": "Bungkus buah muda unggul, buang buah sakit, semprot fungisida tembaga saat hujan."}, {"name": "Lalat Buah", "symptom": "Buah matang berluka basah dengan larva di daging dekat kulit.", "treatment": "Perangkap lalat di kebun, angkat dan kubur buah jatuh, panen sebelum terlalu matang."}]', 'Rp 5.000 – 15.000 / kg')
