insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('duku', 'Duku', 'Lansium parasiticum', 'buah', 'sedang', 2555, 'banyak', 'terang penuh', 'Panen musim hujan akhir (Desember–Maret)', 'Duku adalah buah khas Kalimantan yang sangat disukai — duku Kuaro dari Paser bahkan sudah terkenal sampai luar provinsi dengan harga premium saat musimnya. Buah berkelompok ini manis segar dan selalu laku: dijual ikat/kelompok di pasar, ditadah pengepul, hingga dikirim ke kota besar. Pohonnya besar dan tahan lama, produktif puluhan tahun, dan sangat cocok dengan iklim lembap Kaltim. Meski panen pertama menunggu 6–8 tahun, duku adalah warisan ekonomi keluarga — satu kebun duku bisa jadi sumber pendapatan generasi panjang.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f0b674994d27.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f0b674994d27.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3c31506662d4.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f3c56b349b3e.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b8f2d9629e3e.jpeg"]', '["Pilih bibit dari pohon induk produktif manis (setek udara/sambung) atau benih dari duku terbaik.", "Tanam di lubang 60×60 cm bercampur kandang matang, jarak 9–10 meter antar pohon.", "Siram rutin tahun pertama dan beri mulsa tebal; tanam pisang sementara sebagai peneduh.", "Panen seluruh kelompok saat buah kuning kecokelatan penuh dan kulit mulus — gunting sekelompok bersama tangkai."]', '["Jaga kelembapan sepanjang tahun — duku butuh air cukup saat pengisian buah agar daging tebal.", "Pupuk kandang 20–30 kg/pohon tiap 6 bulan ditambah NPK sebelum musim bunga.", "Pangkas cabut kering dan rapikan tajuk agar cahaya masuk dan buah merata isi.", "Saat pohon mulai berbuah, cadangkan perangkap lalat buah — musim duku adalah musim ramai lalat."]', '[{"name": "Lalat Buah", "symptom": "Kulit berlubang halus dan daging berair busuk dari dalam saat buah mendekati matang.", "treatment": "Perangkap methyl eugenol, angkat buah jatuh dan kubur, panen tepat saat matang penuh."}, {"name": "Kutu Lampung (Penghisap Buah)", "symptom": "Buah muda berbintik cokelat kering dan gugur; kulit tampak lecet seperti luka bakar.", "treatment": "Sempestkan kebersihan kebun, semprot nimba saat buah kecil, pungut serangga manual malam hari."}, {"name": "Busuk Buah di Tandan", "symptom": "Buah dalam satu kelompok berjamur cokelat dan lembek saat musim hujan deras.", "treatment": "Panen segera saat matang, pangkas tandan terinfeksi, dan angkat buah busuk dari bawah pohon."}]', 'Rp 15.000 – 35.000 / kg')
