insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('alpukat', 'Alpukat', 'Persea americana', 'buah', 'sedang', 1460, 'sedang', 'terang penuh', 'Sepanjang tahun, puncak musim kemarau', 'Alpukat adalah buah sehat paling dicari zaman sekarang — permintaan untuk jus, diet, dan kafe membuat harga alpukat mentega dan kiwi stabil tinggi sepanjang tahun. Pohon alpukat tumbuh baik di dataran sedang Kaltim dan mulai berbuah tahun ke-3–4 dari bibit sambung. Satu pohon dewasa bisa menghasilkan ratusan buah, dan pasokan lokal yang masih sedikit membuat peluang pasar sangat terbuka. Alpukat juga tahan simpan lebih lama dari buah tropis lain, cocok untuk pemasaran jarak jauh ke kota.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/7b182767192f.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/7b182767192f.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5f0edeb62c2d.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c37d7e9673e9.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9ddfbe1452cd.jpg"]', '["Tanam bibit sambung unggul (mentega, kiwi) jarak 8×10 meter di lubang bercampur kandang.", "Siram tunta tahun pertama, beri mulsa; alpukat tidak tahan genangan — pilih lahan berdrainase baik.", "Bentuk tajuk terbuka dengan pemangkasan ringan agar cahaya menembus ke seluruh ranting.", "Panen buah dengan tangkai saat kulit kusam dan buah mengapung di air (uji sederhana); matangkan 5–7 hari di tempat teduh."]', '["Pupuk kandang tiap 6 bulan; tambahan kalium saat musim bunga meningkatkan kualitas daging buah.", "Jaga drainase sempurna — alpukat paling rentan mati busuk akar di tanah basah terus.", "Pangkas tinggi pohon agar panen mudah; pohon terlalu tinggi menyulitkan dan berisiko jatuh.", "Panen dengan gunting berangka panjang dan biarkan tangkai 1–2 cm agar buah tidak busuk di pangkal."]', '[{"name": "Busuk Akar Phytophthora", "symptom": "Daun kecil menguning, tajuk menipis dari atas, akar cokelat busuk berbau.", "treatment": "Pastikan drainase, aplikasi Trichoderma/ fungisida sistemik, jangan menanam di tanah genangan."}, {"name": "Antraknosa", "symptom": "Bercak hitam pada kulit buah yang melebar setelah panen saat penyimpanan.", "treatment": "Bungkus buah muda, panen dengan tangkai, simpan di tempat sejuk kering."}, {"name": "Kepik Penghisap", "symptom": "Buah muda gugur dengan bintik cekung gelap di kulit.", "treatment": "Pungut keper manual, bersihkan gulma bawah pohon, semprot nimba rutin."}]', 'Rp 15.000 – 35.000 / kg')
