insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('jambu-bij', 'Jambu Biji', 'Psidium guajava', 'buah', 'mudah', 365, 'sedang', 'terang penuh', 'Sepanjang tahun', 'Jambu biji (jambu batu) adalah buah rakyat paling mudah dan cepat balik modal — bibit cangkok mulai berbuah hanya 8–12 bulan setelah tanam dan panen berulang tiap 3–4 bulan sepanjang tahun. Varietas unggul seperti jambu kristal, merah delima, dan apel memiliki pasar khusus: buah segar, jus, rujak, hingga industri pendamping jambu biji kering. Tanamannya sangat tahan kemarau dan hampir bebas perawatan berat, sempurna untuk pekarangan maupun lahan pinggir. Dengan teknik pangkas paksa, panen bisa diatur jatuh di musim ramai harga tinggi.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/62cd6ae52224.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/62cd6ae52224.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/57a2673b0877.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4166b1e0f981.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/8d308a22c770.jpg"]', '["Tanam bibit cangkok unggul jarak 6×6 meter di lubang bercampur kandang matang.", "Siram tunta tahun pertama; jambu tahan kering tapi produksi naik dengan air cukup.", "Pangkas tajuk menjadi bentuk terbuka agar cahaya masuk dan panen mudah dijangkau.", "Panen buah saat warna hijau pucat/putih dan harum; jambu unggul dipanen setengah matang untuk keropok rujak."]', '["Pupuk kandang tiap 3 bulan; pangkas paksa setelah panen untuk memicu generasi bunga berikutnya.", "Bungkus buah muda dengan kertas agar bebas lalat buah dan kulit mulus bernilai jual tinggi.", "Rutin pangkas tunas air dan cabut kering untuk menjaga produktivitas dan bentuk pohon.", "Saat kubah lalat buah banyak, pasang perangkap di kebun dan angkat buah jatuh setiap hari."]', '[{"name": "Lalat Buah", "symptom": "Buah berluka basah dan busuk dari dalam dengan larva putih di dekat biji.", "treatment": "Bungkus buah muda, perangkap feromon, angkat buah jatuh dan musnahkan."}, {"name": "Karudel (Busuk Kulit)", "symptom": "Kulit batang retak dan mengeluarkan getah kering kecokelatan; ranting kering dari ujung.", "treatment": "Kikis kulit sakit, olesi fungisida+parafin, pangkas dan bakar ranting mati."}, {"name": "Bercak Daun Alga", "symptom": "Bercak kemerahan kasar di daun tua, menyebabkan daun gugur dini.", "treatment": "Semprot fungisida tembaga, jaga kebun bersih dan tajuk terbuka."}]', 'Rp 6.000 – 15.000 / kg')
