insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('nanas', 'Nanas', 'Ananas comosus', 'buah', 'mudah', 330, 'sedikit', 'terang penuh', 'Sepanjang tahun dengan perangsang bunga', 'Nanas adalah buah tanah kering yang sangat cocok untuk lahan marginal Kaltim — tumbuh di tanah masam dan tahan kemarau tanpa irigasi berat. Dari penanaman mahkota/slip hingga panen hanya butuh 10–12 bulan, dan setelahnya tunas samping jadi bibit gratis untuk siklus berikutnya. Pasar nanas stabil: dijual utuh di pasar, dijus warung, hingga kontrak industri manisan nanas. Karena minim perawatan dan tahan tersimpan, nanas adalah buah praktis untuk menambah pendapatan dari lahan yang tak terpakai.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/787b41ba121f.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/787b41ba121f.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bf8d306efb0.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/1c9d683f2fd7.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/793163fe8cba.jpg"]', '["Tanam mahkota/slip nanas unggul (subang, cayenne) di gundukan jarak 40×60 cm pada tanah bercampur kandang.", "Siram secukupnya seminggu pertama; setelah berakar nanas cukup dibiarkan tumbuh sendiri.", "Rutin cabut gulma dan isi ulang tanaman mati; nanas tak butuh naungan sama sekali.", "Panen saat kulit mulai menguning dari bawah dan buah berbau harum (10–12 bulan); putar buah sambil memegang pangkal."]', '["Hindari genangan — nanas mati busuk di tanah becek; tanam di gundukan/bedengan tinggi.", "Pupuk kandang atau NPK tiap 2 bulan memperbesar buah; kurangi nitrogen mendekati panen agar daging padat.", "Perangsang bunga (karbida/etilen) bisa mengatur panen masuk musim harga tinggi.", "Pisahkan tunas samping untuk bibit siklus berikutnya — biaya benih nol di tahun kedua."]', '[{"name": "Busuk Pangkal (Heart Rot)", "symptom": "Daun muda di pusat mudah dicabut dan berbau busuk saat tanah tergenang.", "treatment": "Perbaiki drainase, tanam di gundukan, cabut tanaman mati dan ganti baru."}, {"name": "Lalat Buah", "symptom": "Buah matang berluka basah dan berbau fermentasi dengan larva di dalam.", "treatment": "Panen segera saat mulai menguning, perangkap lalat, dan kubur buah jatuh."}, {"name": "Kekeringan Ujung Daun", "symptom": "Ujung daun kering merah-cokelat massal saat kemarau panjang di tanah pasir.", "treatment": "Beri mulsa daun tebal dan siram seminggu 1–2 kali saat kemarau panjang."}]', 'Rp 4.000 – 10.000 / buah')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kemiri', 'Kemiri', 'Aleurites moluccanus', 'bumbu-dapur', 'mudah', 1800, 'sedikit', 'terang penuh', 'Panen 2–3 kali setahun', 'Kemiri adalah bumbu dasar dapur Indonesia yang tak tergantikan untuk mengental dan mengharumkan gulai, sambal, hingga opor — permintaannya konstan dari rumah tangga hingga industri bumbu siap masak. Pohon kemiri tumbuh besar dan kokoh di lahan Kaltim, tahan kemarau, dan sekali dewasa berbuah 2–3 kali setahun selama puluhan tahun. Selain bumbu, kemiri laku untuk minyak rambut tradisional dan industri kosmetik, memperlebar pasar penjualan. Pohon ini juga cocok sebagai peneduh atau tanaman tepi kebun — sekali tanam jadi tabungan panen tahunan keluarga.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/15e6077f5543.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/15e6077f5543.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ddb0d6e17402.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c40956df89a1.jpg"]', '["Tanam benih segar atau bibit kemiri di lubang 50×50 cm, jarak 10×10 meter (pohon dewasa sangat besar).", "Siram tunta tahun pertama; setelah kokoh kemiri hampir tidak butuh perawatan.", "Bentuk pohon muda dengan pangkas ringan agar ranting rendah dan panen mudah.", "Panen buah saat kulit hijau kecokelatan dan pecah sendiri (4–5 tahun dari tanam); jemur biji hingga kulit arang mudah dikupas."]', '["Hampir bebas perawatan — cukup bersihkan gulma sekitar pohon muda dan pangkas cabut kering.", "Pupuk kandang satu kali setahun memperbesar buah, meski pohon liar pun tetap produktif.", "Jemur panen hingga benar-benar kering sebelum disimpan — kemiri lembap cepat berjamur.", "Simpan biji kering di karung berventilasi; harga lebih baik saat pasokan pasar langka."]', '[{"name": "Ulat Daun", "symptom": "Daun berlubang besar secara serentak saat ulat menghimpun di satu ranting.", "treatment": "Pungut ulat manual atau semprot BT — pohon besar jarang sampai parah."}, {"name": "Busuk Buah", "symptom": "Buah jatuh muda berbintik cokelat busuk saat musim hujan lembap.", "treatment": "Angkat buah jatuh dari kebun, pastikan sirkulasi tajuk baik, semprot tembaga bila berat."}, {"name": "Jamur Tepung di Daun", "symptom": "Lapisan putih seperti debu di daun muda saat musim kering-panas.", "treatment": "Pangkas ranting terlalu rapat, sempestkan sirkulasi; biasanya hilang sendiri musim hujan."}]', 'Rp 30.000 – 60.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('lada', 'Lada', 'Piper nigrum', 'bumbu-dapur', 'sulit', 900, 'sedang', 'teduh sebagian', 'Panen mulai tahun ke-3, tiap 6–8 bulan', 'Lada (merica) adalah rempah yang membuat Kalimantan terkenal di pasar dunia — lada Paser dari Kalimantan Timur dikenal berkualitas tinggi dan harganya mengikuti pasar rempah internasional yang selalu positif. Tanaman rambat ini berpanen panjang: mulai tahun ke-3 dan produktif 15–20 tahun, dipanen butir hijau untuk lada segar atau dibiarkan merah-merah untuk lada kering. Meski budidayanya menuntut ketelitian (thrips, layu, dan phitophtora adalah musuh utama), keuntungan per hektar lada termasuk yang tertinggi di antara rempah. Untuk petani yang serius dengan rempah, lada adalah komoditas investasi jangka panjang dengan pasar yang tak pernah habis.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/799a7de3f37c.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/799a7de3f37c.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c28bc5398c37.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6ed8345ceea7.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/697a211a7a44.jpg"]', '["Pilih stek mata tidur/varietas unggul (Kuching, Bangka) dari kebun sehat bebas penyakit.", "Tanam di guludan dengan tiang tambuk (tutor) hidup/mati, jarak 2×2,5 meter; buat saluran drainase baik.", "Ikatakan sulur ke tiang rutin dan pangkas tunas bawah agar rumpun bercabang rapat.", "Panen ranting berbuah saat butir penuh (mulai tahun ke-3, lalu tiap 6–8 bulan): potong ranting, petik butir."]', '["Mulsa tebal + pupuk kandang tiap 3 bulan — lada sangat responsif terhadap bahan organik.", "Jaga drainase sempurna; akar lada mati busuk bila tergenang lebih dari sehari.", "Kontrol rutin: semprot nimba tiap 10 hari dan inspeksi thrips/bubar di ujung sulur.", "Pangkas rumpun tua dan buang sulur sakit — sanitasi ketat mencegah wabah menyebar antar tanaman."]', '[{"name": "Layu Phitophtora (Phytophthora)", "symptom": "Daun menghitam kering seperti terbakar dan seluruh rumpun layu mendadak dalam hitungan hari.", "treatment": "Cabut dan bakar tanaman sakit, aplikasi fungisida sistemik ke tanah, jaga drainase dan sanitasi."}, {"name": "Bubar (Nematoda)", "symptom": "Rumpun kerdil menguning tanpa sebab jelas; akar bergelembung nodul.", "treatment": "Rotasi lahan, aplikasi bahan organik+Trichoderma, gunakan bibit sehat bebas nematoda."}, {"name": "Thrips Daun", "symptom": "Daun muda menggulung, kaku, dan bercak keperakan — pertumbuhan sulur berhenti.", "treatment": "Semprot minyak nimba atau insektisida daun rutin tiap 7–10 hari saat serangan."}]', 'Rp 25.000 – 45.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('asam-jawa', 'Asam Jawa', 'Tamarindus indica', 'bumbu-dapur', 'mudah', 2500, 'sedikit', 'terang penuh', 'Panen musim kemarau (Juli–Oktober)', 'Asam jawa adalah bumbu penyedap asam wajib dapur Indonesia — sayur asam, asam pedas, sambal, hingga industri saus terus membutuhkannya. Pohonnya luar biasa kuat: tahan kemarau panjang, hidup di tanah kering tak terpakai, dan setelah dewasa berbuah puluhan tahun tanpa perawatan berarti. Buahnya bernilai ganda: daging buah dijual segar/kering, sementara kayu asam yang keras juga bernilai jual. Untuk lahan pinggir kering yang sulit ditanami apa pun, asam jawa adalah pohon tabungan yang nyaris bebas biaya.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bc960bb6e04a.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bc960bb6e04a.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b059dba68cd8.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/e52f759d93d7.jpeg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6838ef1b669e.jpeg"]', '["Rendam benih semalaman lalu semai di polybag hingga tinggi 30–40 cm sebelum ditanam.", "Tanam di lubang kecil jarak 10×10 meter — pohon asam jawa raksasa dan bermahuk lebar.", "Siram tahun pertama saja; setelah akar dalam terbentuk pohon mandiri penuh.", "Panen polong saat kulit cokelat rapuh dan daging padat (6–8 tahun dari tanam); petik/ketuk polong lalu kumpulkan."]', '["Nyaris bebas perawatan — cukup bersihkan semak di bawah pohon saat musim panen memudahkan pungut buah.", "Pangkas cabut bawah saat muda agar buah turun ke ranting yang mudah dijangkau.", "Panen rutin setiap musim — polong tertinggal jadi sarang hama dan tak bernilai.", "Jemur buah 2–3 hari sebelum dijual agar daging kering, tahan simpan, dan harganya lebih baik."]', '[{"name": "Kutu Kampung (Penghisap Daun)", "symptom": "Daun muda menggulung dan lengket; pohon muda pertumbuhannya terhambat.", "treatment": "Semprot air sabun/nimba pada pohon muda; pohon dewasa hampir tak terpengaruh."}, {"name": "Penggerek Polong", "symptom": "Polong berlubang dengan larva di dalam daging, buah tak laku dijual.", "treatment": "Panen tepat waktu dan jemur segera; kutik polong tertinggal di pohon jadi sumber serangan berikutnya."}, {"name": "Jamur Arang", "symptom": "Lapisan hitam seperti jelaga di ranting dan daun dari sekresi kutu lengket.", "treatment": "Kendalikan kutu penghisap dulu, pangkas ranting berjamur tebal."}]', 'Rp 15.000 – 30.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('daun-salam', 'Daun Salam', 'Syzygium polyanthum', 'bumbu-dapur', 'mudah', 540, 'sedang', 'terang', 'Sepanjang tahun', 'Daun salam adalah bumbu wajib masakan Indonesia — rendang, sayur lodeh, ayam goreng, dan sambal goreng selalu menyertakannya, sehingga permintaan pasar sayur tak pernah surut. Pohon salam mudah hidup di pekarangan atau tepi kebun, dan sekali dewasa daunnya bisa dipetik rutin sepanjang tahun. Selain segar, daun salam kering dijual ke industri bumbu dan jamu dengan masa simpan panjang, membuka pasar lebih luas. Untuk petani yang ingin bumbu tanaman-tanaman praktis, salam adalah tanaman sekali tanam panen terus tanpa drama.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/49e83d6bac4a.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/49e83d6bac4a.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/71a7fd93529d.jpeg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/2f1e12a29ef5.jpg"]', '["Tanam stek batang/bibit salam di lubang kecil jarak 4×4 meter; salam juga cocok sebagai pagar hidup kebun.", "Siram tunta hingga tumbuh; salam mudah beradaptasi di hampir semua tanah.", "Pangkas ujung saat pohon 1,5–2 meter agar rumpun bercabang rendah dan petik mudah.", "Mulai petik daun dewasa di usia 15–18 bulan: petik daun muda-dewasa bersama ranting kecil tiap 1–2 bulan."]', '["Pupuk kandang 1–2 kali setahun menjaga daun lebat dan harum pekat.", "Pangkas rumpun rutin agar tetap rendah dan daun muda terus keluar — daun muda lebih laku.", "Petik pagi hari dan jual segera atau jemur — daun segar cepat layu di siang terik.", "Simpan kelebihan panen sebagai daun kering untuk industri bumbu; harga lebih stabil sepanjang tahun."]', '[{"name": "Karat Daun", "symptom": "Bintik oranye-cokelat di permukaan daun yang gugur dini saat lembap berkepanjangan.", "treatment": "Pangkas rumpun agar sirkulasi baik, semprot fungisida tembaga bila menyebar."}, {"name": "Kutu Daun", "symptom": "Pucuk menggulung dan lengket dari koloni kutu kecil hijau.", "treatment": "Semprot air sabun atau nimba; potong pucuk terinfeksi berat."}, {"name": "Busuk Akar", "symptom": "Daun menguning dan rumpun layu saat tanah tergenang lama.", "treatment": "Perbaiki drainase lokasi tanam; salam lebih tahan kering daripada basah."}]', 'Rp 2.000 – 6.000 / ikat')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('daun-jeruk', 'Daun Jeruk Purut', 'Citrus hystrix', 'bumbu-dapur', 'mudah', 450, 'sedang', 'terang penuh', 'Sepanjang tahun', 'Daun jeruk purut adalah aroma khas masakan Nusantara — rendang, urap, sambal matah, dan masakan Thailand selalu membutuhkannya, termasuk pasar restoran Asia di kota besar. Pohon jeruk purut kecil dan cepat: mulai petik daun hanya 12–15 bulan dari bibit cangkok, lalu panen rutin tiap bulan. Minyak atsirinya juga dicari industri kosmetik dan aromaterapi, membuka nilai tambah di luar pasar bumbu. Tanaman ini sangat cocok di pekarangan atau pot besar — satu-dua pohon saja sudah cukup untuk memasok pedagang sayur langganan.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9dfbd3a7f700.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9dfbd3a7f700.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6cd3502941e6.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/7cdc0b542b05.jpg"]', '["Tanam bibit cangkok jeruk purut di lubang/polybag besar bercampur kandang, jarak 3×3 meter.", "Siram tunta dan jaga lembap; jeruk purut menyukai tanah gembur kaya bahan organik.", "Pangkas ujung saat pohon 1 meter agar bercabang rendah dan daun mudah dipetik.", "Petik daun dewasa (bukan pucuk) mulai usia 12–15 bulan, tiap 3–4 minggu; sisakan daun muda agar pohon tetap tumbuh."]', '["Pupuk kandang/kompos tiap 2 bulan — jeruk purut sangat responsif terhadap bahan organik.", "Siram rutin saat kering; daun yang stres air kecil dan kurang harum.", "Pangkas rumpun teratur agar daun tebal dan pohon mudah dipetik dari semua sisi.", "Jual segar dalam ikatan; kelebihan panen bisa dikeringkan untuk pasar bumbu kering dan teh herbal."]', '[{"name": "Kutu Perisai (Diaspis)", "symptom": "Bintik cokelat kecil menempel rapat di ranting dan daun; pucuk mengering.", "treatment": "Semprot minyak nimba/mineral oil tiap 7 hari, pangkas ranting padat terinfeksi."}, {"name": "CVPD (Huanglongbing)", "symptom": "Daun bercak kuning tak simetris, buah kecil pahit; pohon melemah bertahap.", "treatment": "Tidak ada obat — cabut dan musnahkan pohon sakit, gunakan bibit sehat, kendalikan kutu pembawa."}, {"name": "Karat Jeruk", "symptom": "Bintik cokelat kasar seperti karat di daun dan buah muda.", "treatment": "Semprot tembaga + minyak nimba saat tunas muda, jaga kebun bersih dan sirkulasi baik."}]', 'Rp 2.000 – 6.000 / ikat')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('temulawak', 'Temulawak', 'Curcuma xanthorrhiza', 'bumbu-dapur', 'mudah', 300, 'sedang', 'teduh sebagian', 'Sepanjang tahun (panen umbi 9–12 bulan)', 'Temulawak adalah rempah obat khas Indonesia yang kembali populer seiring tren jamu dan minuman sehat — kunyit kuning pahit ini dicari untuk jahe kunyit, serbuk jamu, hingga industri obat herbal. Umbinya tumbuh besar dan cepat (panen 9–12 bulan), tahan hama, dan sangat cocok dengan tanah lembap Kaltim. Pasar bagiannya luas: segar untuk bumbu dan minuman, kering dijual ke pengepul jamu, dan diolah sendiri menjadi serbuk bernilai jual lebih. Seperti jahe dan kunyit, temulawak bisa ditanam di lahan teduh yang jarang dimanfaatkan sayuran lain.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/22d3d727cd81.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/22d3d727cd81.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3a348f29d942.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/48a06723d7a0.jpg"]', '["Pilih rimpang sehat berdaging kuning; tanam langsung di guludan/bedengan teduh jarak 40×50 cm.", "Beri pupuk kandang matang banyak di guludan — temulawak menyukai tanah gembur kaya organik.", "Siram rutin di awal tumbuh; setelah daun lebat tanaman relatif mandiri.", "Panen saat daun mulai mengering (9–12 bulan): gali hati-hati, cuci, dan pilah umbi besar (jual) dan kecil (bibit)."]', '["Mulsa jerami menjaga lembap dan menekan gulma — kerja menggali juga jadi lebih mudah.", "Pupuk kandang tambahan tiap 3 bulan memperbesar umbi; hindari pupuk nitrogen berlebih di akhir masa.", "Naungan parsial (paranet/pohon ringan) menghasilkan umbi lebih besar di dataran rendah panas.", "Simpan bibit umbi kecil di tempat sejuk kering untuk tanam musim berikutnya."]', '[{"name": "Busuk Rimpang", "symptom": "Umbi membusuk berair dari dalam saat tanah tergenang lama.", "treatment": "Pastikan drainase dan guludan tinggi, tanam dengan Trichoderma, hindari lahan becek."}, {"name": "Ulat Daun", "symptom": "Daun berlubang dari larva yang menggulung; mengurangi pengisian umbi.", "treatment": "Semprot BT atau nimba, pungut ulat manual saat pagi."}, {"name": "Bercak Daun", "symptom": "Bercak cokelat kering di daun tua menjelang panen — umumnya tidak mengurangi hasil besar.", "treatment": "Cukup buang daun sakit; pastikan sirkulasi baik dan jarak tanam longgar."}]', 'Rp 15.000 – 30.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kayu-manis', 'Kayu Manis', 'Cinnamomum burmannii', 'bumbu-dapur', 'sulit', 1460, 'sedang', 'terang', 'Kulit batang dipanen setelah 4–6 tahun', 'Kayu manis adalah rempah premium yang dijual hampir semua bentuknya: kulit kering untuk bumbu dan minuman, kayu serbuk industri, hingga minyak atsiri ekspor. Pohonnya tumbuh baik di daerah lembap Kaltim dan setelah 4–6 tahun batangnya sudah siap dikuliti dengan nilai tinggi per kilogram. Budidayanya menuntut kesabaran dan teknik kulit yang benar, namun hasil sekali panen per pohon bisa bernilai ratusan ribu hingga jutaan rupiah. Setelah kuliti, pucuk baru tumbuh lagi sehingga pohon bisa dipanen berulang di masa depan.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d8d134e701a.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d8d134e701a.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0eb1d14b1c03.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0c4728cc4a07.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/67e7e9a2014b.jpg"]', '["Tanam bibit kayu manis di lubang bercampur kandang, jarak 3×3 meter; pilih lahan lembap dan berdrainase baik.", "Siram tunta tahun pertama; beri mulsa dan peneduh sementara bila lahan terbuka.", "Biar pohon tumbuh lurus tanpa cabang bawah — batang lurus menghasilkan kulit kualitas terbaik.", "Panen kulit setelah batang berdiameter 5–8 cm (4–6 tahun): tebang, kuliti batang, dan jemur hingga menggulung kaku."]', '["Pupuk kandang tahunan mempercepat tebal batang — kunci nilai jual ada di diameter kulit.", "Jaga lahan bersih gulma saat pohon muda; setelah besar kayu manis mandiri.", "Kuliti dengan teknik sisi (peeling) yang rapi — kulit utuh menggulung besar harganya jauh lebih baik.", "Jemur kulit 3–5 hari hingga kering kaku lalu pilah per kualitas sebelum dijual ke pengepul rempah."]', '[{"name": "Busuk Akar", "symptom": "Daun menguning dan pohon layu perlahan saat tanah tergenang.", "treatment": "Tanam di lahan berdrainase baik, aplikasi Trichoderma, pangkas bagian mati."}, {"name": "Bercak Daun", "symptom": "Bercak cokelat di daun muda yang menyebar saat musim hujan lembap.", "treatment": "Semprot tembaga, pastikan sirkulasi; pohon dewasa umumnya pulih sendiri."}, {"name": "Penggerek Batang", "symptom": "Lubang kecil dengan serbuk di batang yang menurunkan kualitas kulit.", "treatment": "Tutup lubang dengan parafin+pestisida, buang ranting terinfeksi, jaga pohon sehat."}]', 'Rp 25.000 – 50.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('pala', 'Pala', 'Myristica fragrans', 'bumbu-dapur', 'sulit', 2555, 'banyak', 'teduh sebagian', 'Panen sepanjang tahun setelah dewasa', 'Pala adalah rempah bersejarah Indonesia yang menghasilkan dua produk sekaligus dari satu buah: biji pala dan fuli (selaput mace) — keduanya bernilai tinggi di pasar rempah dunia. Pohon pala menyukai iklim lembap seperti Kaltim dan setelah dewasa berbuah sepanjang tahun tanpa musiman, memberi arus kas rempah rutin. Harga pala kering premium sangat menggiurkan, dan permintaan industri bumbu, minuman, hingga farmasi stabil jangka panjang. Budidayanya menuntut kesabaran (panen pertama 6–8 tahun) dan peneduh muda, namun pohon dewasa produktif puluhan tahun — aset rempah sejati untuk lahan keluarga.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bc77f758325.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bc77f758325.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bfc9997da67.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/135a694efee5.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/17f90428f90c.jpg"]', '["Semai benih segar langsung di polybag (benih pala cepat kehilangan daya tumbuh) hingga siap tanam 6–8 bulan.", "Tanam jarak 8×10 meter dengan tanaman peneduh sementara (pisang/petai) selama 3 tahun pertama.", "Siram rutin dan beri mulsa tebal — pala sangat menyukai kelembapan dan teduh saat muda.", "Panen buah jatuh atau yang pecah sendiri saat matang (mulai tahun ke-6–8); pilah biji dan fuli, jemur keduanya terpisah 5–7 hari."]', '["Tanam pohon jantan dan betina (±1 jantan per 10 betina) — tanaman pala berumah satu jantan-betina terpisah.", "Pupuk kandang tiap 6 bulan dan jaga mulsa tebal sepanjang tahun untuk kelembapan stabil.", "Jangan menguliti/pangkas pohon dewasa — luka besar menyebabkan getah keluar dan pohon melemah.", "Jemur biji hingga bunyi nyaring saat pecah dan fuli hingga kuning kering — kualitas kering menentukan harga."]', '[{"name": "Buah Gugur", "symptom": "Buah muda gugur massal saat kering ekstrem atau angin kencang berkepanjangan.", "treatment": "Jaga mulsa dan penyiraman musim kering; tanam penahan angin di tepi kebun."}, {"name": "Busuk Buah", "symptom": "Buah matang busuk lembek saat hujan lembap berkepanjangan.", "treatment": "Panen buah jatuh setiap hari, jemur segera, dan angkat buah busuk dari kebun."}, {"name": "Kutu Daun dan Kutu Perisai", "symptom": "Pucuk menggulung dan ranting lengket; pertumbuhan pohon muda terhambat.", "treatment": "Semprot minyak nimba rutin, pangkas ranting padat terinfeksi berat."}]', 'Rp 80.000 – 150.000 / kg')
